   817  bool KArchiveFile::copyTo(const QString &dest) const
   818  {
   819      QFile f(dest + QLatin1Char('/')  + name());
   820      if (f.open(QIODevice::ReadWrite | QIODevice::Truncate)) {
   460              bool isDumpDir = false;
   461              if (typeflag == 'D') {
   462                  isdir = false;
   463                  isDumpDir = true;
   464              }
   465              //qCDebug(KArchiveLog) << nm << "isdir=" << isdir << "pos=" << dev->pos() << "typeflag=" << typeflag << " islink=" << ( typeflag == '1' || typeflag == '2' );
   466
   467              if (typeflag == 'x' || typeflag == 'g') { // pax extended header, or pax global extended header
   468                  // Skip it for now. TODO: implement reading of extended header, as per http://pubs.opengroup.org/onlinepubs/009695399/utilities/pax.html
   469                  (void)dev->read(buffer, 0x200);
   470                  continue;
   471              }
   472
   473              if (isdir) {
   474                  access |= S_IFDIR;    // f*cking broken tar files
   475              }
   476
   477              KArchiveEntry *e;
   478              if (isdir) {
   479                  //qCDebug(KArchiveLog) << "directory" << nm;
   480                  e = new KArchiveDirectory(this, nm, access, KArchivePrivate::time_tToDateTime(time), user, group, symlink);
   481              } else {
   482                  // read size
   483                  QByteArray sizeBuffer(buffer + 0x7c, 12);
   484                  qint64 size = sizeBuffer.trimmed().toLongLong(nullptr, 8 /*octal*/);
   485                  //qCDebug(KArchiveLog) << "sizeBuffer='" << sizeBuffer << "' -> size=" << size;
   486
   487                  // for isDumpDir we will skip the additional info about that dirs contents
   488                  if (isDumpDir) {
   489                      //qCDebug(KArchiveLog) << nm << "isDumpDir";
   490                      e = new KArchiveDirectory(this, nm, access, KArchivePrivate::time_tToDateTime(time), user, group, symlink);
   491                  } else {
   492
   493                      // Let's hack around hard links. Our classes don't support that, so make them symlinks
   494                      if (typeflag == '1') {
   495                          //qCDebug(KArchiveLog) << "Hard link, setting size to 0 instead of" << size;
   496                          size = 0; // no contents
   497                      }
   498
   499                      //qCDebug(KArchiveLog) << "file" << nm << "size=" << size;
   500                      e = new KArchiveFile(this, nm, access, KArchivePrivate::time_tToDateTime(time), user, group, symlink,
   501                                           dev->pos(), size);
   502                  }
   503
   504                  // Skip contents + align bytes
   505                  qint64 rest = size % 0x200;
   506                  qint64 skip = size + (rest ? 0x200 - rest : 0);
   507                  //qCDebug(KArchiveLog) << "pos()=" << dev->pos() << "rest=" << rest << "skipping" << skip;
   508                  if (! dev->seek(dev->pos() + skip)) {
   509                      //qCWarning(KArchiveLog) << "skipping" << skip << "failed";
   510                  }
   511              }
   512
   513              if (pos == -1) {
   514                  if (nm == QLatin1String(".")) { // special case
   515                      Q_ASSERT(isdir);
   516                      if (isdir) {
   517                          setRootDir(static_cast<KArchiveDirectory *>(e));
   518                      } else {
   519                          delete e;
   520                      }
   521                  } else {
   522                      rootDir()->addEntry(e);
   523                  }
   524              } else {
   525                  // In some tar files we can find dir/./file => call cleanPath
   526                  QString path = QDir::cleanPath(name.left(pos));
   527                  // Ensure container directory exists, create otherwise
   528                  KArchiveDirectory *d = findOrCreate(path);
   529                  if (d) {
   530                      d->addEntry(e);
   730      strcpy(buffer, "././@LongLink");
   731      qint64 namelen = name.length() + 1;
   732      fillBuffer(buffer, "     0", namelen, QDateTime(), typeflag, uname, gname);
   733      q->device()->write(buffer, 0x200);   // TODO error checking
   734      qint64 offset = 0;
   735      while (namelen > 0) {
   736          int chunksize = qMin(namelen, 0x200LL);
   737          memcpy(buffer, name.data() + offset, chunksize);
   738          // write long name
   739          q->device()->write(buffer, 0x200);   // TODO error checking
   740          // not even needed to reclear the buffer, tar doesn't do it
   741          namelen -= chunksize;
   742          offset += 0x200;
   743      }/*wend*/
   744  }
   745
   746  bool KTar::doPrepareWriting(const QString &name, const QString &user,
   747                              const QString &group, qint64 size, mode_t perm,
   748                              const QDateTime & /*atime*/, const QDateTime &mtime, const QDateTime & /*ctime*/)
   749  {
   750      if (!isOpen()) {
   751          setErrorString(tr("Application error: TAR file must be open before being written into"));
   752          qCWarning(KArchiveLog) << "doPrepareWriting failed: !isOpen()";
   753          return false;
   754      }
   755
   756      if (!(mode() & QIODevice::WriteOnly)) {
   757          setErrorString(tr("Application error: attempted to write into non-writable 7-Zip file"));
   758          qCWarning(KArchiveLog) << "doPrepareWriting failed: !(mode() & QIODevice::WriteOnly)";
   759          return false;
   760      }
   761
   762      // In some tar files we can find dir/./file => call cleanPath
   763      QString fileName(QDir::cleanPath(name));
   764
   765      /*
   766        // Create toplevel dirs
   767        // Commented out by David since it's not necessary, and if anybody thinks it is,
   768        // he needs to implement a findOrCreate equivalent in writeDir.
   769        // But as KTar and the "tar" program both handle tar files without
   770        // dir entries, there's really no need for that
   771        QString tmp ( fileName );
   772        int i = tmp.lastIndexOf( '/' );
   773        if ( i != -1 )
   774        {
   775        QString d = tmp.left( i + 1 ); // contains trailing slash
   776        if ( !m_dirList.contains( d ) )
   777        {
   778        tmp = tmp.mid( i + 1 );
   779        writeDir( d, user, group ); // WARNING : this one doesn't create its toplevel dirs
   780        }
   781        }
   782      */
   783
   784      char buffer[0x201];
   785      memset(buffer, 0, 0x200);
   786      if ((mode() & QIODevice::ReadWrite) == QIODevice::ReadWrite) {
   787          device()->seek(d->tarEnd);    // Go to end of archive as might have moved with a read
   788      }
   789
   790      // provide converted stuff we need later on
   791      const QByteArray encodedFileName = QFile::encodeName(fileName);
   792      const QByteArray uname = user.toLocal8Bit();
   793      const QByteArray gname = group.toLocal8Bit();
   794
   795      // If more than 100 bytes, we need to use the LongLink trick
   796      if (encodedFileName.length() > 99) {
   797          d->writeLonglink(buffer, encodedFileName, 'L', uname.constData(), gname.constData());
   798      }
   799
   800      // Write (potentially truncated) name
   801      strncpy(buffer, encodedFileName.constData(), 99);
   802      buffer[99] = 0;
   803      // zero out the rest (except for what gets filled anyways)
   804      memset(buffer + 0x9d, 0, 0x200 - 0x9d);
   805
   806      QByteArray permstr = QByteArray::number(static_cast<unsigned int>(perm), 8);
   807      permstr = permstr.rightJustified(6, '0');
   808      d->fillBuffer(buffer, permstr.constData(), size, mtime, 0x30, uname.constData(), gname.constData());
   809
   810      // Write header
